# Presets for additional cross-domain SISO ODE models.
def _cross_domain_preset(dt_sim, dt, t_end, hold, tau_u, n=6):
    return {
        "dt_sim": dt_sim, "dt": dt, "t_end": t_end,
        "step_hold_sec": hold, "reference_step_hold_sec": hold,
        "tau_u": tau_u, "plant_n_y": n, "plant_n_u": n,
        "preg_blackbox_enabled": False, "r_preg": 1.0,
        "Tau_1": max(dt, 5.0*dt), "Tau_2": max(2.0*dt, 10.0*dt), "tau_d": tau_u,
        "plant_training_method": "batch", "plant_batch_r_0": 1.0e-4,
        "plant_qnu_batch_r_0": 1.0e-2, "ctrl_learning": "NGD",
        "ctrl_epochs": 8, "mu_v": 0.005, "mu_r_0": 0.0005,
        "ctrl_qnu_learning": "NGD", "ctrl_qnu_epochs": 8,
        "mu_v_qnu": 0.005, "mu_r_0_qnu": 0.0002,
    }

