# Presets and ranges for delayed-input plant variants.
_DELAY_PRESET_BASES = {
    "network_router_fluid_queue_with_delay": "network_router_fluid_queue",
    "network_router_fluid_queue_with_large_delay": "network_router_fluid_queue",
    "cloud_server_workload_with_delay": "cloud_server_workload",
    "microgrid_frequency_bess_nonlinear_with_delay": "microgrid_frequency_bess_nonlinear",
    "soil_moisture_respiration_with_delay": "soil_moisture_respiration",
    "soil_carbon_priming_with_delay": "soil_carbon_priming",
    "accelerator_rf_cavity_amplitude_with_delay": "accelerator_rf_cavity_amplitude",
    "overhead_crane_payload_sway_with_delay": "overhead_crane_payload_sway",
}
for _name, _base in _DELAY_PRESET_BASES.items():
    _p = dict(MODEL_RECOMMENDED_PRESETS[_base])
    _p["plant_n_u"] = max(8, int(_p.get("plant_n_u", 6)) + 3)
    _p["plant_n_y"] = max(8, int(_p.get("plant_n_y", 6)) + 2)
    _p["step_hold_sec"] = max(float(_p["step_hold_sec"]), 4.0 * float(_p["dt"]))
    _p["reference_step_hold_sec"] = _p["step_hold_sec"]
    MODEL_RECOMMENDED_PRESETS[_name] = _p
    MODEL_IO_RANGES[_name] = dict(MODEL_IO_RANGES[_base])


MODEL_IO_RANGES["two_mass_actuator_grounded_m2_lugre2"] = dict(
    MODEL_IO_RANGES["two_mass_actuator_grounded_m2_lugre"]
)

def recommended_preset(model_name):
    preset = MODEL_RECOMMENDED_PRESETS.get(str(model_name))
    if preset is None:
        return None
    result = dict(preset)
    result.update(MODEL_IO_RANGES.get(str(model_name), {}))
    return result
